[tool error]
{
  "ok": false,
  "name": "draw_line",
  "error": {
    "type": "invalid_params",
    "message": "'[3000, 2000 + 14]' is not of type 'array' (at 'start')",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "start": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "[x, y]"
        },
        "end": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "[x, y]"
        }
      },
      "required": [
        "space",
        "start",
        "end"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "start": [
        4100.0,
        7300.0
      ],
      "end": [
        4700.0,
        7300.0
      ],
      "layer": "V-ALIGN-CNTR"
    }
  },
  "warnings": []
}

